const nav=active=>`<nav class="bottom-nav" aria-label="하단 메뉴">${[['home','home','홈'],['history','receipt','주문내역'],['friends','users','동반인'],['my','user-circle','마이페이지']].map(([p,i,n])=>`<button data-go="${p}" class="${p===active?'active':''}" ${p===active?'aria-current="page"':''}>${active==='home'?homeAsset({home:'img12',receipt:'img13',users:'img14','user-circle':'img15'}[i]):icon(i)}${n}</button>`).join('')}</nav>`;
