const money=v=>`€ ${Number(v).toFixed(2)}`;let rate=1550;const won=v=>`약 ${Math.round(v*rate).toLocaleString('ko-KR')}원`;
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem('hanip-v3-'+k))??f}catch{return f}};
const state={page:'home',city:read('city',{ko:'키우시',country:'이탈리아',code:'IT',latitude:43.0157,longitude:11.9489}),cart:read('cart',[]),friends:read('friends',['김미영']),ratings:read('ratings',{}),name:read('name','박성호'),avoid:read('avoid',['버섯','가지']),allergies:read('allergies',[]),prefs:read('prefs',['국물 요리','매콤한 맛']),request:'',photos:[],photoIndex:0,category:'zuppe',review:0,tip:false,tipPercent:5,tipCustom:false,extra:0,query:'',country:'',cityRows:[],searchToken:0,analysis:0,conversationPhase:0,selected:null,nearCategory:'전체',settings:read('settings',{}),connected:true};
const menuEnrichment=createMenuEnrichment({request:requestJson,getMenu:()=>state.liveMenu,onUpdate(){if(['menu','detail'].includes(state.page)){const old=document.querySelector('.scan-detail')||document.querySelector('.scroll');const offset=old?.scrollTop||0;render();const next=document.querySelector('.scan-detail')||document.querySelector('.scroll');if(next)next.scrollTop=offset;}}});
function save(k,v){localStorage.setItem('hanip-v3-'+k,JSON.stringify(v))}let items=[],timers=[],toastTimer;const categoryNames={zuppe:'수프',secondi:'메인 요리',cocktails:'칵테일'};
const photo=i=>{if(i.live)return 'assets/scan-placeholder.svg';const src=i.image?.url||'';return src.startsWith('http')?src:`assets/${i.id}.jpg`};
const foodName=i=>i.korean||i.original;const find=id=>items.find(i=>i.id===id);const sum=()=>state.cart.reduce((s,r)=>s+(find(r.id)?.price||0)*r.qty,0);const count=()=>state.cart.reduce((s,r)=>s+r.qty,0);const selected=(id,owner)=>state.cart.find(r=>r.id===id&&r.owner===owner)?.qty||0;
const warning=i=>[...new Set([...state.avoid,...state.allergies])].filter(a=>(i.ingredients?.join(' ')+i.description+foodName(i)+allergenText(i)).includes(a));
function clearTimers(){timers.forEach(clearTimeout);timers=[]}function later(fn,ms){timers.push(setTimeout(fn,ms))}
function go(page){if(['camera','analysis'].includes(page))menuEnrichment.cancel();if(state.page==='camera'&&page!=='camera')realCamera.stop();if(state.page==='analysis'&&page!=='analysis'){scanController?.abort();scanController=null}clearTimers();state.page=page;$('#overlay').innerHTML='';render();if(page==='analysis')runScan();if(page==='camera')mountCamera();if(page==='menu'&&!state.liveMenu&&state.friends.length&&!state.companionDemo&&!state.cart.some(r=>r.owner!=='나')){state.companionDemo=true;later(()=>{add(items[2].id,state.friends[0],false);toast(`${state.friends[0]}님이 담았어요`,items[2]);render()},4200)}if(page==='conversation'){state.conversationPhase=0;render();conversationPrompt()}if(page==='destination')startSearch();if(['nearby','asian'].includes(page))void loadExplorer(page);location.hash=page}
function toast(text,item,duration=2000){clearTimeout(toastTimer);$('#toast').innerHTML=`${item?`<img src="${photo(item)}" alt="">`:icon('check')}<div><b>${esc(text)}</b>${item?`<small>${esc(foodName(item))}</small>`:''}</div>`;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),duration)}
function add(id,owner='나',show=true){let r=state.cart.find(r=>r.id===id&&r.owner===owner);if(r)r.qty++;else state.cart.push({id,owner,qty:1});save('cart',state.cart);if(show)toast('장바구니에 담았어요',find(id))}
function change(id,owner,delta){let r=state.cart.find(r=>r.id===id&&r.owner===owner);if(r)r.qty+=delta;state.cart=state.cart.filter(r=>r.qty>0);save('cart',state.cart);render()}
function foodCard(i){const mine=selected(i.id,'나'),theirs=state.cart.filter(r=>r.id===i.id&&r.owner!=='나'),flags=warning(i);return `<article class="food-card" data-detail="${i.id}" role="button" tabindex="0" aria-label="${esc(foodName(i))} 상세 보기"><div class="food-photo"><img src="${photo(i)}" alt="${esc(foodName(i))}" loading="lazy">${flags.length?`<div class="food-photo-warnings">${flags.map(t=>`<span>${esc(t)} 포함</span>`).join('')}</div>`:''}${mine||theirs.length?`<div class="selection" aria-label="이 메뉴를 담은 사람">${mine?`<span class="selection-person selection-self">나 ${mine}개</span>`:''}${theirs.map(r=>`<span class="selection-person selection-companion">${esc(r.owner)} ${r.qty}개</span>`).join('')}</div>`:''}<button class="add ${mine?'is-mine':''}" data-add="${i.id}" aria-label="${esc(foodName(i))} 담기">${icon(mine?'check':'plus')}</button></div><div class="food-copy"><span class="original">${esc(i.original)}</span><h3>${esc(foodName(i))}</h3><p>${esc(i.listDescription||i.description)}</p><div class="menu-price-line"><span class="price">${money(i.price)}</span><span class="won">${won(i.price)}</span></div></div></article>`}

function home(){return wrap(`<div class="home-content"><div class="between home-top"><button class="location-pill" data-go="destination">${homeAsset('img')}${esc(state.city.country)} · ${esc(state.city.ko)} ${homeAsset('img1')}</button><span class="home-companion-profile" role="img" aria-label="${state.friends.length?esc(state.friends[0])+'님과 여행 중':'혼자 여행 중'}" title="${state.friends.length?esc(state.friends[0])+'님과 여행 중':'혼자 여행 중'}">${friendAvatar(state.friends[0])}</span></div><div class="home-scan-hero"><h1 class="home-heading"><span>메뉴판을 찍으면</span><span>번역부터 주문까지</span></h1><button class="home-camera-circle" data-go="camera" aria-label="메뉴판 찍기">${homeAsset('img2')}</button></div><div class="two-col"><button class="quick-card" data-go="menu">${homeAsset('img3')}<b>방금 본 메뉴판</b><small>${esc(state.liveMenu?(state.restaurant?.name||state.liveMenu.restaurantName||'촬영한 메뉴판'):'Osteria La Solita Zuppa')}</small></button><button class="quick-card" data-go="review">${homeAsset('img4')}<b>평가 안 한 메뉴</b><small>2개 남았어요</small></button></div><button class="home-link home-nearby-banner" data-go="nearby"><img class="nearby-banner-map home-figma-map" src="assets/figma-home-20261103/imgFrame.svg" alt="" aria-hidden="true"><span class="nearby-banner-icon">${homeAsset('img5')}</span><span class="home-link-label"><b>내 주변 식당 찾기</b>${homeAsset('img6')}</span></button><div class="ranking"><div class="home-ranking-heading"><h2 class="section-label">실시간 음식 순위</h2><button class="home-ranking-all" data-go="ranking" aria-label="실시간 음식 순위 전체 보기"><span>전체 보기</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button></div><div class="home-rank-list">${ranked().slice(0,5).map((i,n)=>`<button class="home-rank-row" ${i.regional?`data-rank="${i.id}"`:`data-detail="${i.id}"`}>${i.regional?`<span class="home-rank-photo home-rank-illustration" aria-hidden="true">${i.emoji||'🍽'}</span>`:`<img class="home-rank-photo" src="${photo(i)}" alt="">`}<span class="home-rank-number">${n+1}</span><span class="home-rank-copy"><span class="home-rank-name">${esc(foodName(i))}</span><span class="home-rank-original">${esc(i.regional?(i.restaurantName||i.original||''):'Osteria La Solita Zuppa')}</span></span><span class="home-rank-score" aria-label="평점 ${esc(ratingData(i).score)}">${homeAsset('imgFrame1')} ${esc(ratingData(i).score)}</span></button>`).join('')}</div></div></div>`,'home')}
function foodRankingQuote(i){const quotes={"ZUPPA DI PORRI E PATATE":"감자죽처럼 부드럽고 대파 향이 은은해요.","ZUPPA DI ZUCCA E FARRO":"달지 않은 호박죽에 밀알이 톡톡 씹혀요.","ZUPPA DI CECI E PORCINI":"버섯 향이 진하고 콩이 들어 든든해요.","CINGHIALE IN SALMI'":"장조림처럼 진한 풍미, 와인 향이 매력적이에요.","BACCALA' ALLA FIORENTINA":"바삭한 대구에 토마토 소스가 잘 어울려요."};return quotes[i.original]||i.listDescription||i.analogy||i.description||'익숙한 재료에 현지의 풍미가 더해져요.';}
function ratingSamples(i){const idx=items.findIndex(x=>x.id===i.id);return idx===2?[5,5,5,4,5]:idx===3?[5,4,5]:idx===7?[5,4,4,5]:[5,4,5]}
function ratingData(i){if(i.live)return {score:'—',count:0,quote:i.listDescription||'아직 평가가 없어요.',own:false};
 const samples=ratingSamples(i);
 const own=state.ratings[i.id],values=own===undefined?samples:[...samples,[5,3,1][own]];

 return {score:(values.reduce((a,b)=>a+b,0)/values.length).toFixed(1),count:values.length,quote:own===undefined?foodRankingQuote(i):["또 먹고 싶어요.","한 번이면 충분해요.","제 입맛에는 조금 아쉬웠어요."][own],own:own!==undefined};
}
const roundedRatingStar='<svg class="detail-rounded-star" width="26" height="26" viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.4L12 17.6l-5.7 3 1.1-6.4-4.6-4.5 6.4-.9Z" fill="currentColor" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg>';
function ratingLine(i,detail=false){const r=ratingData(i);return `<div class="rating-line ${detail?'detail-rating-line':''}"><span class="rating-score"><span class="rating-star">${detail?roundedRatingStar:'★'}</span> ${r.score}</span><span class="rating-scale">/ 5</span>${detail?`<button class="rating-count detail-review-link" data-show-reviews="${esc(i.id)}" aria-label="리뷰 ${r.count}개 전체 보기">리뷰 ${r.count}개</button>`:`<span class="rating-count">리뷰 ${r.count}개</span>`}</div>`;}
function rankingQuote(i,showOwn=true){const r=ratingData(i);return `<p class="ranking-quote">${esc(showOwn?r.quote:foodRankingQuote(i))}</p>${showOwn&&r.own?'<span class="my-review-label">내 평가 반영</span>':''}`;}
function ranked(){if(!/키우시|치우시/.test(state.city.ko)){let list=(foodCatalog[state.city.code]||foodCatalog.IT).filter(i=>!i.dessert);const seed=Array.from(state.city.name||state.city.ko).reduce((n,c)=>n+c.codePointAt(0),0)%list.length;return Array.from({length:Math.min(5,list.length)},(_,n)=>({...list[(seed+n)%list.length],id:'regional-'+n,regional:true}));}let base=state.city.code==='IT'?[items[2],items[3],items[7],items[4],items[0]]:[items[4],items[3],items[2],items[7],items[0]];return base.filter(Boolean).sort((a,b)=>Number(ratingData(b).score)-Number(ratingData(a).score))}
function camera(){return wrap(`<div class="camera-screen"><video id="menu-camera" autoplay playsinline muted aria-label="메뉴판 카메라 미리보기"></video><div class="camera-shade"></div><div class="topbar"><button class="icon-btn" data-action="flash" aria-label="플래시">${icon('flash')}</button><strong>${state.photos.length?'다음 장도 찍어주세요':'메뉴판을 찍어주세요'}</strong><button class="icon-btn" data-go="home" aria-label="촬영 닫기">${icon('close')}</button></div><div class="viewfinder"><div class="corner"></div></div><div id="camera-message" class="camera-message" role="status">카메라를 여는 중이에요</div><div class="camera-tools"><div class="shutter-row"><button class="icon-btn" data-action="album" aria-label="앨범에서 선택">${icon('image')}</button><button class="shutter" data-action="capture" aria-label="메뉴판 촬영"></button>${state.photos.length?`<button class="thumb-stack real-thumb" data-go="photos" aria-label="촬영 사진 ${state.photos.length}장 보기"><img src="${state.photos.at(-1)}" alt="마지막 촬영 사진"><b aria-hidden="true">${state.photos.length}</b></button>`:'<div style="width:43px"></div>'}</div>${state.photos.length?btn(`메뉴판 ${state.photos.length}장 해석하기`,goAttr('analysis')):''}</div></div>`)}
function photos(){return wrap(`${top('촬영한 메뉴판','camera')}<div class="scroll"><div class="between" style="margin-bottom:17px"><h2>총 ${state.photos.length}장</h2><button class="pill" data-go="camera">+ 더 찍기</button></div><div class="photo-grid">${state.photos.map((p,n)=>`<div class="photo-preview"><button data-delete-photo="${n}" aria-label="${n+1}번째 사진 삭제">×</button><div data-enlarge-photo="${n}" style="height:100%;cursor:zoom-in">${p?`<img src="${p}" alt="촬영 사진 ${n+1}">`:`<div style="background:#fcf7ed;padding:35px 12px;font-size:11px;height:100%"><b>Osteria<br>La Solita Zuppa</b><br><br>— ZUPPE —<br><br>Zuppa di ceci e porcini<br>Zuppa di melanzane fumé<br>Zuppa di porri e patate<br>Zuppa di zucca e farro<br><br>— SECONDI —</div>`}</div></div>`).join('')}</div>${!state.photos.length?'<div class="empty">촬영한 사진이 없어요.</div>':''}</div><div class="fixed-bottom">${btn('메뉴판 해석하기',`${goAttr('analysis')} ${!state.photos.length?'disabled':''}`)}</div>`)}
function analysis(preview=false){return wrap(`${top('메뉴판 해석','photos')}<div class="analysis"><h2>${state.scanError?'해석을 잠시<br>멈췄어요':'메뉴판을<br>한국인 입맛으로<br>풀어드리는 중이에요'}</h2><div class="card">${[['메뉴판 읽고 한국식으로 해석하기',preview?'메뉴판의 글씨를 확인하고 있어요':`${state.photos.length}장의 사진을 확인하고 있어요`],['식당 정보 찾기','메뉴판의 식당명으로 후보를 찾아요']].map(([t,sub],n)=>`<div class="progress-row ${state.analysis>n?'done':state.analysis===n&&!state.scanError?'busy':'wait'}"><span class="progress-circle">${state.analysis>n?'✓':''}</span><div><b>${t}</b><small>${sub}</small></div></div>`).join('')}</div>${state.scanError?`<div class="info-card" role="alert"><p>${esc(state.scanError)}</p><br>${btn('다시 해석하기','data-action="retry-scan"')}${btn('사진 확인하기',goAttr('photos'),'secondary')}</div>`:`<p class="subtle-note">${preview?'디자인 미리보기 · 실제 사진 분석은 진행하지 않아요.':'잠시만 기다려주세요. 사진은 별도로 저장하지 않아요.'}</p>`}</div>`)}

let nearbyPlaces=[],asianPlaces=[],explorerSearchSerial=0;
function explorerPlace(p,n,mode){const text=p.type||p.primaryType||'음식점',categories=mode==='asian'?[/korean|한식/i.test(text+' '+p.name)?'한식당':/market|grocery|마켓|식료/i.test(text+' '+p.name)?'아시안 마켓':'아시안 식당']:[/피자|pizza/i.test(text+' '+p.name)?'피자':/파스타|pasta/i.test(text)?'파스타':/수프|soup/i.test(text)?'수프':'고기 요리'];return {...p,id:p.id||mode+'-'+n,name:p.name||'이름 확인 필요',type:text,address:p.address||'',rating:Number(p.rating)||0,reviews:Number(p.ratingCount||p.reviews||p.userRatingCount)||0,categories,source:p.maps||p.source||'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.name+' '+state.city.ko),image:null,facts:[],description:p.description||''}}
async function loadExplorer(mode){const serial=++explorerSearchSerial,category=state.nearCategory;state.explorerLoading=true;state.explorerError='';nearbyPlaces=[];asianPlaces=[];render();try{const locality=`${state.city.name||state.city.ko} ${state.city.country}`,name=category==='한식당'?`Korean restaurants in ${locality}`:category==='아시안'?`Asian restaurants in ${locality}`:'';const r=await requestJson('/api/menu/places',{name,location:state.explorerMapCenter||{lat:state.city.latitude||43.0159475,lng:state.city.longitude||11.9468233}});if(serial!==explorerSearchSerial)return;const rows=(r.places||[]).filter(p=>p.businessStatus!=='CLOSED_PERMANENTLY').map((p,n)=>explorerPlace(p,n,mode));if(mode==='asian')asianPlaces=rows;else nearbyPlaces=rows;}catch(e){if(serial!==explorerSearchSerial)return;state.explorerError='식당 정보를 불러오지 못했어요. 다시 시도해주세요.'}finally{if(serial===explorerSearchSerial){state.explorerLoading=false;if(state.page===mode)render()}}}
function mountExplorerMap(){const target=$('#nearby-google-map');if(!target)return;const rows=state.page==='asian'?asianPlaces:nearbyPlaces;mountGoogleMap(target,rows,state.explorerMapCenter||{lat:state.city.latitude||43.0159475,lng:state.city.longitude||11.9468233},id=>openPlace(id),position=>{state.explorerMapCenter=position;void loadExplorer(state.page)})}
function placeById(id){return [...nearbyPlaces,...asianPlaces].find(p=>p.id===id)}
function placeImage(p,large=false){return p.image?`<img class="${large?'place-cover-image':'place-thumb'}" src="${p.image}" alt="${esc(p.name)}">`:`<div class="${large?'place-cover-art':'place-thumb place-thumb-art'}" aria-hidden="true">${p.glyph||'🍽'}</div>`}
function placeRating(p){if(!p.rating)return '<div class="place-rating"><span>평점 정보 없음</span></div>';return `<div class="place-rating"><strong>${p.rating.toFixed(1)}</strong><span class="place-stars" style="--rating-fill:${p.rating/5*100}%">★★★★★</span><span>(${p.reviews.toLocaleString('ko-KR')})</span>${p.price?`<span>· ${p.price}</span>`:''}</div>`}
function placeMap(p){const lat=p?.lat||state.city.latitude||43.0159475,lng=p?.lng||state.city.longitude||11.9468233;return `<div class="map"><div class="map-fallback"></div><iframe title="${p?esc(p.name):'주변 장소'} 지도" src="https://www.openstreetmap.org/export/embed.html?bbox=${lng-.004}%2C${lat-.0027}%2C${lng+.004}%2C${lat+.0027}&layer=mapnik&marker=${lat}%2C${lng}" loading="lazy"></iframe></div>`}
function openPlace(id,from=state.page){const p=placeById(id);if(!p)return;state.placeId=id;state.placeOrigin=['nearby','asian','restaurant'].includes(from)?from:state.placeOrigin||'nearby';go('place')}
function placeExplorer(mode){const categories=['전체','아시안','한식당'];if(!categories.includes(state.nearCategory))state.nearCategory='전체';const places=mode==='asian'?asianPlaces:nearbyPlaces;return wrap(`<div class="map-screen place-explorer"><div class="map explorer-google-map" id="nearby-google-map" aria-label="주변 식당 Google 지도"></div>${top('내 주변 식당 찾기', 'home')}<div class="map-sheet"><button class="handle" data-action="sheet" aria-label="장소 목록 펼치기"></button><div class="sheet-scroll"><span class="restaurant-region">${esc(state.city.country)} · ${esc(state.city.ko)}</span><div class="tabs place-categories">${categories.map(c=>`<button class="${state.nearCategory===c?'active':''}" data-near-category="${c}" aria-pressed="${state.nearCategory===c}">${c}</button>`).join('')}</div><div class="place-results">${state.explorerLoading?'<p class="explorer-status" role="status">주변 식당을 찾고 있어요.</p>':''}${!state.explorerLoading&&state.explorerError?`<p class="explorer-status" role="alert">${esc(state.explorerError)}</p><button class="explorer-retry" data-go="${mode}">다시 찾기</button>`:''}${!state.explorerLoading&&!state.explorerError&&!places.length?'<p class="explorer-status">조건에 맞는 식당을 찾지 못했어요.</p>':''}${places.map(p=>`<button class="place-result" data-place="${p.id}"><div class="place-result-copy"><h3>${esc(p.name)}</h3>${placeRating(p)}<p>${esc(p.type)}</p><small>${esc(p.address||state.city.ko)}</small>${state.savedPlaces?.includes(p.id)?'<span class="place-saved-label">저장됨</span>':''}</div>${placeImage(p)}</button>`).join('')}<p class="explorer-google-credit" translate="no">Google Maps</p></div></div></div></div>`)}
function placeDetails(){const p=placeById(state.placeId)||nearbyPlaces[0],saved=state.savedPlaces?.includes(p.id),query=encodeURIComponent(p.name+' '+state.city.ko),maps=p.source||'https://www.google.com/maps/search/?api=1&query='+query,directions='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(p.id==='solita'?p.lat+','+p.lng:p.name+' '+(p.sample?state.city.ko:'Chiusi'));return wrap(`<div class="map-screen place-details">${restaurantGoogleMap(p)}${top('',state.placeOrigin||'nearby')}<div class="map-sheet"><button class="handle" data-action="sheet" aria-label="장소 정보 펼치기"></button><div class="sheet-scroll"><div class="place-detail-heading"><h2>${esc(p.name)}</h2>${placeRating(p)}<p>${esc(p.type)}</p></div><div class="place-actions"><a href="${directions}" target="_blank" rel="noopener" class="place-action primary-place-action">${icon('pin')}<span>길찾기</span></a><button class="place-action ${saved?'saved':''}" data-save-place="${p.id}" aria-pressed="${!!saved}">${icon('heart')}<span>${saved?'저장됨':'저장'}</span></button><a href="${maps}" target="_blank" rel="noopener" class="place-action">${icon('globe')}<span>구글 지도</span></a></div>${p.image?`<div class="place-gallery">${placeImage(p,true)}</div>`:''}<div class="place-about"><h3>장소 정보</h3><p>${esc(p.description)}</p><div class="place-facts">${p.facts.map(t=>`<span>${esc(t)}</span>`).join('')}</div></div><div class="place-info-row">${icon('pin')}<span>${esc(p.address||state.city.country+' · '+state.city.ko)}</span></div><a class="place-info-row" href="${maps}" target="_blank" rel="noopener">${icon('star')}<span>평점 ${p.rating.toFixed(1)} · 리뷰 ${p.reviews.toLocaleString('ko-KR')}개<small>리뷰와 영업시간 확인하기 ↗</small></span></a>${p.website?`<a class="place-info-row" href="${p.website}" target="_blank" rel="noopener">${icon('globe')}<span>웹사이트<small>${esc(new URL(p.website).hostname)}</small></span></a>`:''}${p.phone?`<a class="place-info-row" href="tel:${p.phone}">${icon('mic')}<span>${esc(p.phone)}</span></a>`:''}</div></div></div>`)}
function restaurantGoogleMap(p){const query=encodeURIComponent(p.name+' '+(p.address||'Chiusi'));return `<div class="map restaurant-google-embed"><iframe title="${esc(p.name)} Google 지도" src="https://maps.google.com/maps?q=${query}&z=17&output=embed&hl=ko" loading="eager" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>`}
async function loadPreviewNearby(){
 if(state.previewNearbyStarted||!state.restaurantPreview?.restaurant)return;
 state.previewNearbyStarted=true;
 try{const center=state.restaurantPreview.restaurant;const r=await requestJson('/api/menu/places',{name:'',location:{lat:center.lat,lng:center.lng}});state.restaurantPreview.nearby=nearbyRestaurants(center,r.places||[]);if(state.page==='restaurant'&&!state.liveMenu){const sheet=$('.map-sheet'),top=sheet?.style.top,expanded=sheet?.classList.contains('expanded'),scroll=$('.sheet-scroll')?.scrollTop;render();if(expanded)$('.map-sheet')?.classList.add('expanded');if(top)$('.map-sheet').style.top=top;if(scroll)$('.sheet-scroll').scrollTop=scroll;}}
 catch(e){console.warn('주변 식당 사진을 불러오지 못했어요.');}
}
function mapBase(mode){
 if(mode!=='restaurant')return placeExplorer(mode);if(state.liveMenu)return scannedRestaurant();
 const data=state.restaurantPreview||{restaurant:{name:'Osteria La Solita Zuppa',lat:43.0159475,lng:11.9468233},nearby:[]};
 return wrap(`<div class="map-screen restaurant-confirm-screen">${restaurantGoogleMap(data.restaurant)}${top('','camera')}<div class="map-sheet"><button class="handle" data-action="sheet" aria-label="식당 패널 펼치기"></button><div class="sheet-scroll"><span class="restaurant-region">이탈리아 · 토스카나</span><h2 class="restaurant-sheet-title">Osteria La Solita Zuppa</h2><p class="restaurant-cuisine">수프 · 파스타 · 고기 요리</p><img class="restaurant-hero" src="assets/restaurant-google.jpg" alt="Osteria La Solita Zuppa의 실제 실내 · 구글맵 소유자 제공 사진">${btn('이 식당이 맞아요',goAttr('menu'),'primary restaurant-confirm-action')}<section class="restaurant-nearby" aria-label="근처의 다른 식당"><div class="restaurant-nearby-heading"><h3>근처의 다른 식당</h3></div>${nearbyRestaurants(data.restaurant,data.nearby).map(p=>`<article class="restaurant-nearby-item"><div class="restaurant-nearby-row"><a class="restaurant-nearby-photo" href="${esc(p.maps)}" target="_blank" rel="noopener" aria-label="${esc(p.name)} 지도에서 보기">${p.photo?`<img src="${esc(apiAssetUrl(p.photo.url))}" alt="${esc(p.name)} 식당 사진" loading="lazy" onerror="this.hidden=true;this.parentElement.classList.add('missing')">`:`${icon('image')}`}</a><div class="restaurant-nearby-copy"><a class="restaurant-nearby-title" href="${esc(p.maps)}" target="_blank" rel="noopener"><b>${esc(p.name)}</b></a><small class="restaurant-photo-credit">${p.photo?.authors?.length?p.photo.authors.map(a=>a.url?`<a href="${esc(a.url)}" target="_blank" rel="noopener">${esc(a.name)}</a>`:esc(a.name)).join(' · ')+' · ':''}Google Maps</small><span class="restaurant-nearby-meta"><span>${esc(p.type)}</span><span class="restaurant-nearby-distance">${Math.round(p.distance)}m</span></span></div></div></article>`).join('')}${!nearbyRestaurants(data.restaurant,data.nearby).length?'<p class="subtle-note">700m 이내의 다른 식당을 찾지 못했어요.</p>':''}</section></div></div></div>`)
}
function menu(){if(state.liveMenu)return scannedMenu();return wrap(`${top('메뉴를 골라주세요','restaurant')}<div class="menu-header"><div class="between"><div class="row"><div class="avatars"><span class="avatar">나</span>${state.friends.length?`<span class="avatar">${state.friends[0][0]}</span>`:''}</div><b class="small" style="color:#636977">${state.friends.length?esc(state.friends[0])+'님과 함께 고르는 중':'나만의 메뉴를 고르는 중'}</b></div><button class="small blue" data-action="invite">초대</button></div><div class="tabs menu-category-tabs" role="tablist" aria-label="메뉴 카테고리">${['zuppe','secondi','cocktails'].map(c=>`<button class="${state.category===c?'active':''}" data-category="${c}" role="tab" aria-selected="${state.category===c}">${categoryNames[c]}<span>${items.filter(i=>i.category===c).length}</span></button>`).join('')}</div></div><div class="scroll" style="padding-top:0"><div class="food-grid">${items.filter(i=>i.category===state.category).map(foodCard).join('')}</div><p class="subtle-note">공식 웹메뉴 보관 자료 · 2026.10.10<br>원화는 시연 환율 €1 = ${rate.toLocaleString()}원 기준이에요.</p></div><div class="fixed-bottom">${btn(`${icon('bag')} <span>${count()}개</span><span style="margin-left:auto">장바구니 가기</span>`,goAttr('cart'))}</div>`)}
function detail(){if(state.liveMenu)return scannedDetail();const i=find(state.selected)||items[0],pumpkin=i.original==='ZUPPA DI ZUCCA E FARRO',inferred=i.inferredIngredients?.length?i.inferredIngredients:i.category==='zuppe'?['양파','올리브유','채소 육수']:i.category==='cocktails'?['얼음','과일 껍질']:['육수','조리용 기름'];const originals={'호박':'zucca','파로':'farro','병아리콩':'ceci','포르치니 버섯':'porcini','후추':'pepe','엑스트라 버진 올리브 오일':'olio extra vergine di oliva'};return wrap(`<button class="icon-btn detail-natural-back" data-go="menu" aria-label="메뉴 목록으로"><img src="assets/figma-detail-back.svg" width="20" height="20" alt=""></button><div class="detail-natural-scroll detail-figma detail-reference"><button class="detail-hero detail-photo-button" data-detail-photo="${esc(i.id)}" aria-label="${esc(foodName(i))} 사진 크게 보기"><img src="${i.id==='2928bddd-77b5-4aab-b2de-f6c1450add5a'?'assets/figma-detail-soup.png':photo(i)}" alt="${esc(foodName(i))}"></button><div class="detail-body"><div class="detail-meta-row"><span class="original">${esc(i.original)}</span>${warning(i).length?`<div class="detail-ingredient-badges">${warning(i).map(t=>`<span class="detail-ingredient-badge">${esc(t)} 포함</span>`).join('')}</div>`:''}</div><h2 class="reference-menu-name">${esc(pumpkin?'호박과 고대 밀 수프':foodName(i))}</h2><div class="reference-price-row"><div class="detail-price"><span>EUR</span><b>${i.price.toFixed(2)}</b><small>${won(i.price)}</small></div><button class="reference-review" data-show-reviews="${esc(i.id)}">리뷰 ${ratingData(i).count}개</button></div><section class="reference-ai-card"><div class="reference-card-heading"><span class="reference-ai-icon" aria-hidden="true">✦</span><div><h3>한국 음식으로 치면</h3><p>AI가 한국 음식에 빗대어 설명했어요</p></div></div><h4>${esc(pumpkin?'보리를 넣은 걸쭉한 호박죽에 가까워요':analogyHeadline(i))}</h4><p class="reference-ai-description">${esc(pumpkin?'호박죽보다 덜 달고, 치즈와 올리브유 덕에 고소한 맛이 나요.':i.analogy||cocktailAnalogy(i))}</p></section><section class="info-card reference-official"><div class="reference-card-heading"><span class="reference-check" aria-hidden="true">${icon('check')}</span><div><h3>메뉴판에 적힌 정보</h3><p>메뉴판 원문에서 확인했어요</p></div></div><div class="divider"></div><small>재료</small><div class="reference-ingredient-list">${(i.ingredients||[]).map(t=>`<div class="reference-ingredient"><p>${esc(t)}${originals[t]?`<span>${esc(originals[t])}</span>`:''}</p>${t==='파로'?'<small>보리처럼 톡톡 씹히는 고대 밀</small>':''}</div>`).join('')||'<p>명시된 재료가 없어요.</p>'}</div><div class="divider"></div><small>알레르기</small><p class="reference-allergen">${esc(allergenText(i))}</p><p class="reference-allergen-note">메뉴판 원문에 적혀 있어요.</p></section><section class="reference-ai-card reference-inferred"><div class="reference-card-heading"><span class="reference-ai-icon" aria-hidden="true">✦</span><div><h3>AI가 추정한 정보</h3><p>일반적인 ${pumpkin?'토스카나 ':''}레시피 기준이라 다를 수 있어요</p></div></div><div class="divider"></div><small>들어갈 수 있는 재료</small><div class="reference-tags">${inferred.map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="divider"></div><small>조리법</small><p class="reference-inferred-copy">${esc(pumpkin?'호박을 푹 끓여 곱게 간 뒤, 따로 삶은 파로를 넣어 죽처럼 걸쭉하게 만드는 게 일반적이에요.':i.cooking||generalInfo(i))}</p><div class="divider"></div><small>알레르기 가능성</small><p class="reference-inferred-copy">${pumpkin?'유제품 (EU 7)':esc([...new Set([...state.allergies,...warning(i)])].join(' · ')||'추가 재료 확인 필요')}</p><p class="reference-allergen-note">${pumpkin?'파르메산 치즈가 들어가요.': '육수와 추가 재료, 교차 접촉 여부를 확인해주세요.'}</p><button class="reference-staff-phrase" data-detail-phrase="${esc(i.id)}">직원에게 확인하는 문장 보기</button></section><p class="reference-detail-note">재료와 조리법은 식당마다 다를 수 있어요.</p></div></div><div class="fixed-bottom reference-detail-footer">${btn(`<span>장바구니에 담기</span><small>EUR ${i.price.toFixed(2)}</small>`,`data-add="${i.id}"`)}</div>`)}
function analogyHeadline(i){const k=items.indexOf(i);return ['콩죽에 버섯 향을 더한 느낌이에요','구운 가지나물을 수프로 즐기는 느낌이에요','대파의 단맛을 더한 부드러운 감자죽 같아요','밀알을 넣은 고소한 호박죽에 가까워요'][k]||({'cocktails':'과일 향과 쌉싸름함을 즐기는 식전주예요'}[i.category])||foodName(i)}
function cocktailAnalogy(i){return i.original==='AMERICANO'?'커피가 아니라 칵테일이에요. 탄산이 있는 쌉싸름한 식전주로 떠올려보세요.':i.original.includes('SPRITZ')?'과일 향 탄산주처럼 가볍게 마시는 스타일이지만, 쌉싸름한 맛이 함께 느껴질 수 있어요.':'달콤하고 쌉싸름한 향을 즐기는 이탈리아 식전주예요. 실제 도수와 배합은 직원에게 확인해주세요.'}
function allergenText(i){let m=i.officialDescription?.match(/Allergeni[:.]?\s*([^V\n]+)/i)||i.officialDescription?.match(/ALLEREGENI[.:]?\s*(.*)/i);const names={1:'글루텐 함유 곡물',2:'갑각류',3:'달걀',4:'생선',5:'땅콩',6:'대두',7:'우유·유제품',8:'견과류',9:'셀러리',10:'겨자',11:'참깨',12:'아황산염',13:'루핀',14:'연체동물'};return m?[...new Set((m[1].match(/\d+/g)||[]).map(n=>names[n]?names[n]+' (EU '+n+')':n))].join(' · ')||'자세한 알레르기 정보는 직원에게 확인해주세요.':'상세 알레르기 정보는 직원에게 확인해주세요.'}
function generalInfo(i){if(i.category==='cocktails')return cocktailAnalogy(i);if(i.original.includes('PORCINI'))return '포르치니는 향이 진한 버섯이에요. 구수한 국물과 숲 향을 떠올리면 이해하기 쉬워요.';if(i.original.includes('MELANZANE'))return '부드러운 가지에 장작의 훈연 향, 치즈의 짭짤하고 고소한 풍미가 어우러질 수 있어요.';if(i.original.includes('FARRO'))return '호박의 은은한 단맛과 파로 밀알의 톡톡 씹히는 식감이 대비되는 수프예요.';if(i.original.includes('PATATE')&&i.category==='zuppe')return '서양 대파를 익히면 매운맛이 줄고 단맛이 살아나요. 감자 덕분에 부드럽고 포근한 식감을 기대할 수 있어요.';return i.analogy||'한국 음식과는 양념이 다르지만, 주재료와 조리법을 기준으로 맛을 떠올려보세요. 실제 간과 식감은 식당의 조리에 따라 달라요.'}
function cart(){let owners=[...new Set(state.cart.map(r=>r.owner))].sort((a,b)=>a==='나'?-1:b==='나'?1:0);return wrap(`${top('함께 담은 장바구니','menu')}<div class="cart-content" style="--cart-groups:${Math.max(1,owners.length)}">${!state.cart.length?`<div class="empty">${icon('bag')}<h3>아직 담은 메뉴가 없어요</h3><p>마음에 드는 메뉴를 골라보세요.</p><br>${btn('메뉴 둘러보기',goAttr('menu'),'secondary')}</div>`:owners.map(owner=>`<div class="cart-group ${owner==='나'?'cart-owner-self':'cart-owner-companion'}"><div class="cart-title"><span class="cart-owner-avatar">${owner==='나'?'나':esc(owner.slice(0,1))}</span><span class="cart-owner-name">${owner==='나'?'내 메뉴':esc(owner)+'님 메뉴'}</span> <span class="muted small">· ${state.cart.filter(r=>r.owner===owner).reduce((s,r)=>s+r.qty,0)}개</span></div><div class="cart-items" data-cart-owner="${esc(owner)}" role="region" aria-label="${owner==='나'?'내':esc(owner)+'님'} 음식 목록" tabindex="0">${state.cart.filter(r=>r.owner===owner).map(r=>{let i=find(r.id);return `<div class="cart-item"><img src="${photo(i)}" alt="${esc(foodName(i))}"><div class="copy"><span class="original">${esc(i.original)}</span><h3>${esc(foodName(i))}</h3><div class="cart-price-line"><span class="price">${money(i.price)}</span><span class="won">${won(i.price)}</span></div><button class="cart-remove" data-remove="${r.id}" data-owner="${esc(owner)}" aria-label="${esc(foodName(i))} 삭제">${icon('close')}</button><div class="stepper"><button data-qty="${r.id}" data-owner="${esc(owner)}" data-delta="-1" aria-label="수량 줄이기">−</button><span>${r.qty}</span><button data-qty="${r.id}" data-owner="${esc(owner)}" data-delta="1" aria-label="수량 늘리기">${icon('plus')}</button></div></div></div>`}).join('')}</div><div class="total-line"><span>${owner==='나'?'내':esc(owner)+'님'} 합계</span><b>${money(state.cart.filter(r=>r.owner===owner).reduce((s,r)=>s+find(r.id).price*r.qty,0))}</b></div></div>`).join('')}</div><div class="fixed-bottom"><div class="cart-tip-controls"><label class="tip-check"><input type="checkbox" id="tip" ${state.tip?'checked':''}>선택 팁 포함</label><div class="tip-rate-controls"><span class="tip-select-shell"><select id="tip-percent" aria-label="팁 비율 선택">${[5,10,15].map(v=>`<option value="${v}" ${!state.tipCustom&&state.tipPercent===v?'selected':''}>${v}%</option>`).join('')}<option value="custom" ${state.tipCustom?'selected':''}>직접 입력</option></select></span>${state.tipCustom?`<label class="tip-custom-field"><span class="sr-only">팁 비율 직접 입력</span><input id="tip-custom" type="number" inputmode="decimal" min="0" max="100" step="0.1" value="${state.tipPercent}" aria-label="팁 비율 직접 입력"><span aria-hidden="true">%</span></label>`:''}</div></div><div class="summary-row"><span>음식 ${money(sum())}</span><span id="cart-tip-amount">${state.tip?'선택 팁 '+money(sum()*state.tipPercent/100):'팁 미포함'}</span></div><div class="summary-total"><div><b>예상 총액</b><small id="cart-total-won" style="display:block">총 ${count()}개 · ${won(total())}</small></div><strong id="cart-total-amount">${money(total())}</strong></div>${btn('주문 문장 만들기',`${goAttr('order')} ${!state.cart.length?'disabled':''}`)}</div>`)}
const total=()=>sum()*(1+(state.tip?state.tipPercent/100:0));
function orderSentences(){let lines=state.cart.map(r=>({i:find(r.id),qty:r.qty}));if(!lines.length)lines=[{i:items[2],qty:1},{i:items[3],qty:1}];let ko=lines.map(r=>`${foodName(r.i)} ${r.qty}개`).join(', ')+' 주세요.';let it='Vorremmo ordinare '+lines.map(r=>`${r.qty===1?'una porzione di':r.qty+' porzioni di'} ${r.i.original.toLowerCase()}`).join(' e ')+', per favore.';let request=requestTranslation(state.request);return{ko:ko+(state.request?' '+state.request:''),it:it+(request?' '+request:'')}}
function requestTranslation(text){if(!text.trim())return'';if(text.includes('훈제')&&text.includes('가지')&&text.includes('치즈'))return 'La zuppa di melanzane affumicate senza formaggio, per favore.';let parts=[];const ingredients=[['치즈','formaggio'],['고수','coriandolo'],['버섯','funghi'],['가지','melanzane'],['소금','sale'],['양파','cipolla'],['땅콩','arachidi'],['새우','gamberi']];for(const [ko,it]of ingredients)if(text.includes(ko))parts.push(`${/추가|더|넣어/.test(text)?'Con un po’ di '+it+' in più':'Senza '+it}, per favore.`);if(/맵지|안 맵|덜 맵/.test(text))parts.push('Non piccante, per favore.');if(/물/.test(text))parts.push('Potremmo avere anche dell’acqua, per favore?');if(/따로/.test(text))parts.push('A parte, per favore.');return parts.join(' ')}
function order(){let s=orderSentences();return wrap(`${top('주문하기','cart')}<div class="scroll order-content"><div class="card order-card"><span class="order-language">한국어</span><h2 id="order-ko">${esc(s.ko)}</h2><div class="divider"></div><div class="between order-language-row"><span class="order-language">이탈리아어</span><div class="order-actions"><button class="icon-btn" data-action="speak-order" aria-label="주문 문장 듣기">${icon('sound')}</button><button class="icon-btn" data-go="enlarged" aria-label="주문 문장 확대">${icon('expand')}</button></div></div><p class="italian" id="order-it">${esc(s.it)}</p></div><label class="field-label" for="request">요청사항</label><textarea class="request" id="request" placeholder="입력하면 주문 문장에 바로 반영돼요.&#10;예: 치즈는 빼주세요">${esc(state.request)}</textarea><p class="subtle-note" id="request-status" role="status" aria-live="polite"></p></div><div class="fixed-bottom order-footer">${btn('실시간 대화하기',goAttr('conversation'))}<button class="text-link" data-action="finish-order">주문했어요 · 영수증 보기</button></div>`)}
function enlarged(){return wrap(`${top('직원에게 보여주세요','order',`<button class="icon-btn" data-action="speak-order" aria-label="음성 재생">${icon('sound')}</button>`)}<div class="fullscreen-text">${esc(orderSentences().it)}</div>`)}
function conversationPrompt(){modal(`<div class="preview"><small>주문 문장</small><p>${esc(orderSentences().ko)}</p><p>${esc(orderSentences().it)}</p></div><h2>아까 만든 주문 문장을<br>먼저 보여줄까요?</h2><div class="actions">${btn('네, 보여줄게요','data-action="show-order"')}${btn('아니요, 바로 말하기','data-action="skip-order"','secondary')}</div>`)}
function conversation(){let phase=state.conversationPhase;return wrap(`<div class="conversation"><div class="conversation-half staff ${phase===2?'speaking':''}"><div class="caption">ITALIANO · STAFF<button class="icon-btn" data-action="speak-staff" aria-label="이탈리아어 듣기">${icon('sound')}</button></div><div>${phase===1?`<div class="speech-current other initial-order">${esc(orderSentences().it)}</div>`:phase===2?'<div class="speech-history other">La zuppa di melanzane affumicate senza formaggio, per favore.</div><div class="speech-current self">Certamente,<br>va bene.</div>':'<div class="speech-current other muted">Possiamo iniziare<br>a parlare.</div>'}</div><div class="mic-row"><button class="mic-button" data-action="staff-speak">${icon('mic')} Parla</button>${phase===2?'<span>Sto parlando…</span>':''}</div></div><button class="conversation-end" data-action="finish-order">× &nbsp;대화 마치기</button><div class="conversation-half ${phase===3?'speaking':''}"><div class="caption">한국어 · 나<button class="icon-btn" data-action="speak-korean" aria-label="한국어 듣기">${icon('sound')}</button></div><div>${phase>=2?'<div class="speech-history self">훈제 가지 수프에 치즈는 빼주세요.</div><div class="speech-current other">네, 알겠습니다.</div>':`<div class="speech-current muted" style="font-size:20px">${phase===1?'직원에게 주문 문장을<br>보여주고 있어요.':'편하게 말해주세요.'}</div>`}</div><div class="between"><div class="mic-row"><button class="mic-button" data-action="my-speak">${icon('mic')} 말하기</button><span>${phase===3?'듣고 있어요…':'한국어로 말해주세요'}</span></div><div class="wave">${'<i></i>'.repeat(7)}</div></div></div></div>`)}
function receiptValues(){const rows=(state.lastOrder?.cart||state.cart).filter(r=>find(r.id));const subtotal=rows.reduce((v,r)=>v+find(r.id).price*r.qty,0);const coperto=Number(state.receiptCharges?.coperto)||0,water=Number(state.receiptCharges?.water)||0,extra=Number(state.extra)||0,tip=Number(state.lastOrder?.tipAmount)||0;return {rows,subtotal,coperto,water,extra,tip,total:subtotal+coperto+water+extra+tip}}
function receiptAmount(amount,cls=''){return `<span class="receipt-money ${cls}"><small>EUR</small><b>${Number(amount).toFixed(2)}</b></span>`}
function updateReceiptTotals(){const v=receiptValues();if($('#extra-amount'))$('#extra-amount').textContent=money(v.extra);if($('#receipt-total'))$('#receipt-total').textContent=v.total.toFixed(2);if($('#receipt-won'))$('#receipt-won').textContent=won(v.total);if($('#receipt-total-note'))$('#receipt-total-note').textContent=v.water?'확인한 물 요금 포함':'물 요금 미포함'}
function receipt(){const v=receiptValues(),people=state.friends.length+1;return wrap(`${top('영수증 미리보기','history')}<div class="scroll receipt-scroll"><h2 class="receipt-intro">계산서에 붙을 금액을<br>미리 정리했어요</h2><div class="receipt receipt-paper"><header class="receipt-restaurant"><h3>${esc(state.restaurant?.name||'Osteria La Solita Zuppa')}</h3><p>${esc(state.lastOrder?.createdAt?new Date(state.lastOrder.createdAt).toLocaleDateString('ko-KR'):'2026.10.26')} · ${people}명</p></header><div class="receipt-rule dashed"></div><div class="receipt-menu-rows">${v.rows.length?v.rows.map(r=>{const i=find(r.id);return `<div class="receipt-grid-row"><span>${esc(foodName(i))}${r.qty>1?' × '+r.qty:''}</span>${receiptAmount(i.price*r.qty)}</div>`}).join(''):'<p class="small">아직 주문한 메뉴가 없어요.</p>'}</div><div class="receipt-rule dashed"></div><div class="receipt-charge"><div class="receipt-grid-row"><span>코페르토 · ${people}명</span><label class="receipt-fee-input"><small>EUR</small><input id="receipt-coperto" type="number" min="0" max="10000" step="0.1" inputmode="decimal" value="${v.coperto||''}" placeholder="미확인" aria-label="확인한 코페르토 합계"></label></div><p class="receipt-cost-note"><span aria-hidden="true">ⓘ</span><span>빵·식기·자리 준비 비용이에요. 식당에서 확인한 금액을 입력해주세요.</span></p></div><div class="receipt-charge"><div class="receipt-grid-row"><span>물 (시켰다면)</span><label class="receipt-fee-input"><small>+EUR</small><input id="receipt-water" type="number" min="0" max="10000" step="0.1" inputmode="decimal" value="${v.water||''}" placeholder="미확인" aria-label="확인한 물 요금"></label></div><p class="receipt-cost-note"><span aria-hidden="true">ⓘ</span><span>병에 든 물은 별도 요금일 수 있어요. 주문했다면 계산서의 금액을 확인해주세요.</span></p></div><div class="receipt-grid-row receipt-tip-row"><span>선택 팁${v.tip?' '+state.lastOrder.tipPercent+'%':''}</span>${receiptAmount(v.tip)}</div><details class="receipt-extra-editor"><summary>추가 요금 수정</summary><label for="extra">기타 확인한 추가 요금 (EUR)</label><input class="input" id="extra" type="number" min="0" max="10000" step="0.5" value="${v.extra||''}" placeholder="확인한 금액만 입력"><span id="extra-amount" class="small">${money(v.extra)}</span></details><div class="receipt-rule"></div><div class="receipt-total-grid"><div><b>예상 합계</b><small id="receipt-total-note">${v.water?'확인한 물 요금 포함':'물 요금 미포함'}</small></div><div class="receipt-total-price"><span class="receipt-money"><small>EUR</small><strong id="receipt-total">${v.total.toFixed(2)}</strong></span><small id="receipt-won">${won(v.total)}</small></div></div></div><p class="receipt-disclaimer">식당이 발행한 영수증이 아니에요. 실제 계산서와 다를 수 있어요.</p><div class="receipt-actions">${btn('홈으로 가기',goAttr('home'))}${btn('추가 주문하기',goAttr('menu'),'secondary')}</div></div>`).replace('class="screen ','class="screen receipt-screen ')}
function historyPage(){return wrap(`${top('주문내역')}<div class="scroll"><div class="card between"><div><h3>오늘의 한 끼는 어땠나요?</h3><small>평가가 남은 메뉴 ${Math.max(0,3-Object.keys(state.ratings).length)}개</small></div><button class="pill active" data-go="review">평가하기</button></div><p class="history-date">2026.10.26 월요일</p><div class="history-card"><div class="history-thumbs">${[items[2],items[3]].map(i=>`<img src="${photo(i)}" alt="${esc(foodName(i))}">`).join('')}<span>+1</span></div><h3>Osteria La Solita Zuppa</h3><p class="small">키우시 · 김미영님과 2명 · 수프 2, 메인 1</p><div class="between" style="margin-top:20px"><span class="small">예상 합계</span><b style="font-size:18px">${money(state.lastOrder?state.lastOrder.total:36)}</b></div><div class="history-actions"><button data-go="order">주문 문장</button><button data-go="receipt">영수증</button></div></div><p class="history-date">2026.10.24 토요일</p><button class="history-card row" style="width:100%;text-align:left" data-action="old-order"><img src="${photo(items[7])}" style="width:48px;height:48px;object-fit:cover;border-radius:15px" alt="지난 식사"><span><b>Trattoria Da Rosa</b><small style="display:block">피렌체 · 2명 · EUR 38.50</small></span><span style="margin-left:auto">›</span></button></div>`,'history')}
function review(){let list=[items[2],items[3],items[7]],i=list[state.review];if(!i)return wrap(`${top('오늘의 맛 기록','history')}<div class="scroll rating-saved">${icon('heart')}<h2>오늘의 맛을 기억했어요</h2><p class="muted">평가가 내 취향과<br>실시간 음식 순위에 반영됐어요.</p><br>${btn('내 취향 추천 보기',goAttr('ranking'))}</div>`);return wrap(`${top('오늘의 맛 기록','history')}<div class="scroll"><div class="review-progress">${list.map((_,n)=>`<span class="${n<=state.review?'active':''}"></span>`).join('')}</div><h2 style="font-size:21px;font-weight:500">${esc(foodName(i))},<br>입맛에 맞으셨어요?</h2><img class="review-image" src="${photo(i)}" alt="${esc(foodName(i))}">${[['heart','또 먹고 싶어요','한국인 평점에 반영돼요'],['user','한 번이면 충분해요',''],['close','입맛에 안 맞아요','']].map(([ic,t,s],n)=>`<button class="review-option ${state.ratings[i.id]===n?'selected':''}" data-rating="${n}" data-item="${i.id}">${icon(ic)}<span>${t}${s?`<small>${s}</small>`:''}</span></button>`).join('')}</div>`)}
function friends(){return wrap(`${top('동반인')}<div class="scroll"><p class="friends-trip-label">${esc(state.city.country)} · ${esc(state.city.ko)} 여행 중</p><div class="between" style="margin:7px 0 19px"><h2 style="font-size:21px">이번 여행 동반인 <span class="small">${state.friends.length}</span></h2><button class="pill white" data-action="invite">${icon('users')} 초대</button></div>${state.friends.length?state.friends.map(n=>`<div class="card row companion-card" style="padding:19px 15px;margin-bottom:12px"><span class="avatar" style="width:42px;height:42px">${friendAvatar(n)}</span><button data-edit-friend="${n}" style="text-align:left"><b>${n}</b><small style="display:block">${friendDescription(n)}</small></button><button class="pill" style="margin-left:auto;background:#fff;border:1px solid #e5e8ef" data-friend-remove="${n}">빼기</button></div>`).join(''):'<div class="card muted">동반인을 초대해 함께 메뉴를 골라보세요.</div>'}<div class="between" style="margin:25px 0 7px"><h3>친구 목록</h3><button class="small" data-action="new-friend">+ 새 친구</button></div>${['김미영','박정숙','김영수',...state.friends.filter(n=>!['김미영','박정숙','김영수'].includes(n))].map(n=>`<div class="friend-row"><span class="avatar">${friendAvatar(n)}</span><button data-edit-friend="${n}" style="text-align:left;padding:0"><h3>${esc(n)}</h3><small>${friendDescription(n)}</small></button>${state.friends.includes(n)?'<span class="small" style="margin-left:auto;font-size:10px">함께하는 중</span>':`<button class="pill" data-friend-add="${esc(n)}">추가</button>`}</div>`).join('')}<p class="subtle-note" style="text-align:center;margin-top:26px">이름을 누르면 동반인 정보를 수정할 수 있어요.<br>연결된 동반인은 같은 메뉴판과 장바구니를 함께 봐요.</p></div>`,'friends')}
const friendAvatar=n=>{const src=state.friendPhotos?.[n];return src&&/^data:image\/(jpeg|png|webp);base64,/.test(src)?`<img src="${esc(src)}" alt="">`:`<span>${esc(n?n.slice(-2):'나')}</span>`};
async function saveFriendProfile(name){try{const file=$('#friend-photo')?.files?.[0];if(file){const data=await readPhoto(file);const image=new Image();image.src=data;await image.decode();const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const edge=Math.min(image.width,image.height);canvas.getContext('2d').drawImage(image,(image.width-edge)/2,(image.height-edge)/2,edge,edge,0,0,256,256);state.friendPhotos={...state.friendPhotos,[name]:canvas.toDataURL('image/jpeg',.85)};save('friendPhotos',state.friendPhotos)}state.friendNotes??={};state.friendNotes[name]=$('#friend-note').value;save('friendNotes',state.friendNotes);$('#overlay').innerHTML='';render()}catch(error){toast(error.message||'프로필을 저장하지 못했어요.')}}
const friendDescription=n=>state.friendNotes?.[n]||({'김미영':'새우 알레르기 · 토마토 못 먹어요','박정숙':'갑각류 알레르기 · 고수 못 먹어요','김영수':'견과류 알레르기 · 양고기 못 먹어요'}[n]||'알레르기·못 먹는 음식 미등록');
function my(){return wrap(`${top('마이페이지')}<div class="scroll stack"><div class="card"><div class="row"><span class="avatar" style="width:51px;height:51px;font-size:21px;background:#e5e9f7">${esc(state.name.slice(-1))}</span><div><h3 style="font-size:20px">${esc(state.name)}님</h3><small>${esc(state.city.country)} · ${esc(state.city.ko)} 여행 중<br>카카오 계정으로 로그인 중</small></div><button class="icon-btn" style="margin-left:auto;background:#f2f2f5" data-action="edit-profile" aria-label="프로필 수정">${icon('edit')}</button></div><div class="profile-stat"><button data-go="history"><strong>${state.lastOrder?13:12}</strong><small>주문 기록</small></button><button data-go="review"><strong>${18+Object.keys(state.ratings).length}</strong><small>평가한 메뉴</small></button><button data-go="friends"><strong>${state.friends.length}명</strong><small>동반인</small></button></div></div><div class="card"><div class="between"><h3>내 입맛</h3><button class="small blue" data-action="taste">수정</button></div><div class="tags">${(state.allergies.length?state.allergies.map(a=>a+' 알레르기'):['알레르기 없음']).concat(state.avoid.map(a=>a+' 못 먹어요')).map(t=>`<span style="background:#f2f2f5;color:#80848f">${esc(t)}</span>`).join('')}${state.prefs.map(p=>`<span style="background:#eaf0ff;color:#5e75cc">${esc(p)} 좋아해요</span>`).join('')}</div></div><div class="card" style="padding:2px 20px"><button class="settings-row" data-go="friends"><span>${icon('users')} &nbsp; 함께 여행하는 사람</span><span>›</span></button><button class="settings-row" data-go="settings"><span>${icon('shield')} &nbsp; 개인정보와 설정</span><span>›</span></button><button class="settings-row" data-go="destination" style="border:0"><span>${icon('pin')} &nbsp; 여행 국가·도시 변경</span><span>›</span></button></div></div>`,'my')}
function settings(){return wrap(`${top('설정','my')}<div class="scroll"><div class="card"><h3>기본 설정</h3><button class="settings-row" data-action="edit-profile">사용자 정보 관리 <span>›</span></button><label class="settings-row">사용 언어<select id="language" style="border:0;background:none;color:#8e96a7"><option>한국어</option><option>English</option><option>Italiano</option></select></label><button class="settings-row" data-go="destination">여행 국가 및 지역 <span class="small">${esc(state.city.country)} · ${esc(state.city.ko)} ›</span></button></div><div class="card" style="margin-top:12px"><h3>사용 환경</h3><label class="settings-row">글자 크기<select id="font-size" style="border:0;background:none"><option value="normal">기본</option><option value="large" ${state.settings.font==='large'?'selected':''}>크게</option></select></label>${['알림 받기','카메라 접근','마이크 접근','위치 접근'].map(t=>`<label class="settings-row">${t}<input class="toggle" type="checkbox" data-setting="${t}" ${state.settings[t]!==false?'checked':''}></label>`).join('')}<p class="subtle-note">프로토타입의 설정 상태예요. 실제 기기 권한은 변경하지 않아요.</p></div><div class="card" style="margin-top:12px"><h3>서비스 관리</h3>${['사용 안내','개인정보 및 저장','서비스 정보'].map(t=>`<button class="settings-row" data-help="${t}">${t}<span>›</span></button>`).join('')}</div></div>`)}
function countryFlag(code){return /^[A-Z]{2}$/.test(code||'')?String.fromCodePoint(...code.split('').map(c=>127397+c.charCodeAt(0))):'🌍'}
function destination(){return wrap(`${top('여행지 설정')}<div class="scroll destination-content"><h2 class="destination-title">어디로 여행 가시나요?</h2><label class="searchbox destination-search">${icon('search')}<input id="city-query" value="${esc(state.query)}" placeholder="국가 또는 도시 검색" autocomplete="off" aria-label="국가 또는 도시 검색">${state.query?'<button data-action="clear-search" aria-label="검색 지우기">×</button>':''}</label><h3 class="current-destination-label">현재 여행지</h3><button class="current-destination" data-go="home" aria-label="현재 여행지 ${esc(state.city.country)} ${esc(state.city.ko)}"><span class="country-flag" aria-hidden="true">${countryFlag(state.city.code)}</span><span class="destination-copy"><b>${esc(state.city.country)} · ${esc(state.city.ko)}</b><small>${esc(state.city.name||'Chiusi')}</small></span><span class="destination-check">✓</span></button><select class="country-select" id="country-select" aria-label="국가 선택"><option value="">유럽 전체 국가</option>${europeanCountries.map(c=>`<option value="${c.code}" ${state.country===c.code?'selected':''}>${c.flag} ${c.name}</option>`).join('')}</select><div class="between" style="margin:22px 0 7px"><h3 id="search-heading" style="font-size:14px">${state.query?'검색 결과':state.country?'이 나라의 도시':'추천 여행지'}</h3><span class="small" id="search-status">검색 준비 중</span></div><div id="city-results">${cityResults()}</div></div>`)}
function cityResults(){return state.cityRows.length?state.cityRows.map((r,n)=>`<button class="city-result" data-city="${n}"><span class="country-flag" aria-hidden="true">${countryFlag(r.code)}</span><span><b>${esc(r.country||'')} · ${esc(r.ko||r.name)}</b><small>${[r.name,r.region].filter(Boolean).map(esc).join(' · ')}</small></span><span class="chevron">›</span></button>`).join(''):'<div class="empty" style="padding:35px 0">검색어를 입력하면 도시를 찾아드려요.</div>'}
let worker=new Worker('./city-worker.js',{type:'module'});worker.onmessage=({data})=>{if(data.token!==state.searchToken||state.page!=='destination')return;if(data.rows)state.cityRows=data.rows;if($('#city-results'))$('#city-results').innerHTML=cityResults();if($('#search-status'))$('#search-status').textContent=data.error?'연결을 확인해주세요':data.loading?'전체 지명 확인 중…':`${data.total??state.cityRows.length}곳`};
function startSearch(){if($('#search-heading'))$('#search-heading').textContent=state.query?'검색 결과':state.country?'이 나라의 도시':'추천 여행지';state.searchToken++;const country=europeanCountries.find(c=>c.name.includes(state.query)&&state.query.length>0);worker.postMessage({token:state.searchToken,q:country?'':state.query,code:country?.code||state.country});if($('#search-status'))$('#search-status').textContent='검색 중…'}
function ranking(){return wrap(`${top('실시간 음식 순위')}<div class="scroll"><span class="eyebrow">TASTE OF ${esc(state.city.name||state.city.ko).toUpperCase()}</span><h2 style="margin:7px 0 10px">${esc(state.city.ko)}에서 찾은<br>우리 입맛에 맞는 한 끼</h2><p class="small" style="margin-bottom:23px">여행자들의 맛 기록과 내 취향을 함께 반영했어요.</p>${ranked().map((i,n)=>`<button class="rank-list" style="width:100%;text-align:left" ${i.regional?`data-rank="${i.id}"`:`data-detail="${i.id}"`}><em>${n+1}</em>${i.regional?`<div class="rank-illustration">${i.emoji||'🍽'}</div>`:`<img src="${photo(i)}" alt="${esc(foodName(i))}">`}<span><h3>${esc(foodName(i))}</h3>${ratingLine(i)}${rankingQuote(i)}<small class="rank-restaurant">${i.regional?esc(state.city.country)+'의 대표 음식':'Osteria La Solita Zuppa'}</small></span></button>`).join('')}<p class="subtle-note">별점과 한 줄 평은 디자인 확인을 위한 시연 데이터예요. 내 평가는 5·3·1점으로 환산되어 이 기기의 평균 점수에 반영돼요.</p></div>`)}
function render(){const cartScrolls=new Map(state.page==='cart'?[...document.querySelectorAll('.cart-items')].map(el=>[el.dataset.cartOwner,el.scrollTop]):[]);const views={home,camera,photos,analysis,'analysis-preview':()=>analysis(true),restaurant:()=>mapBase('restaurant'),nearby:()=>mapBase('nearby'),asian:()=>mapBase('asian'),place:placeDetails,menu,detail,cart,order,enlarged,conversation,receipt,history:historyPage,review,friends,my,settings,destination,ranking};$('#app').innerHTML=(views[state.page]||home)();if(['nearby','asian'].includes(state.page))mountExplorerMap();if(state.page==='cart')document.querySelectorAll('.cart-items').forEach(el=>{el.scrollTop=cartScrolls.get(el.dataset.cartOwner)||0});document.title=(state.page==='home'?'한입 — 유럽 미식 가이드':'한입 · '+({menu:'메뉴판',cart:'장바구니',conversation:'마주보기 대화',destination:'여행지 검색'}[state.page]||'유럽 미식 여행'));$('.device').classList.toggle('camera-mode',state.page==='camera');$('.device').classList.toggle('large-type',state.settings.font==='large');document.documentElement.style.setProperty('--user-font-scale',state.settings.font==='large'?'1.1':'1');if(state.page==='settings'&&state.settings.font==='large')$('#app').style.fontSize='15px';else $('#app').style.fontSize='';if(state.page==='camera')queueMicrotask(mountCamera);if(state.page==='restaurant'&&state.liveMenu)queueMicrotask(mountScannedMap);if(state.page==='restaurant'&&!state.liveMenu)queueMicrotask(loadPreviewNearby)}

function showDetailReviews(id){const i=find(id);if(!i)return;const r=ratingData(i),samples=i.live?[]:ratingSamples(i),own=state.ratings[id];modal(`<div class="detail-reviews-dialog"><h2>리뷰 ${r.count}개</h2><p class="review-menu-name">${esc(foodName(i))}</p><div class="review-dialog-score"><span aria-hidden="true">★</span> ${r.score}<small> / 5</small></div>${samples.length?`<p class="review-data-label">예시 평가</p>${samples.map((score,n)=>`<article class="detail-review-entry"><div class="between"><b>평가 ${n+1}</b><span class="review-entry-score"><span aria-hidden="true">★</span> ${score.toFixed(1)}</span></div>${n===0?`<p>${esc(foodRankingQuote(i))}</p>`:''}</article>`).join('')}`:''}${own!==undefined?`<article class="detail-review-entry own-review"><div class="between"><b>내 평가</b><span class="review-entry-score"><span aria-hidden="true">★</span> ${[5,3,1][own].toFixed(1)}</span></div><p>${esc(["또 먹고 싶어요.","한 번이면 충분해요.","제 입맛에는 조금 아쉬웠어요."][own])}</p></article>`:''}${!r.count?'<p class="empty">아직 작성된 리뷰가 없어요.</p>':''}</div>`)}
function showDetailPhoto(id){const i=find(id);if(!i)return;const src=i.id==='2928bddd-77b5-4aab-b2de-f6c1450add5a'?'assets/figma-detail-soup.png':photo(i);modal(`<figure class="detail-photo-viewer"><img src="${esc(src)}" alt="${esc(foodName(i))} 전체 사진"><figcaption>${esc(foodName(i))}</figcaption></figure>`)}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.detail-photo-viewer,.detail-reviews-dialog')){$('#overlay').innerHTML=''}});

function modal(content){$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal" aria-label="닫기">${icon('close')}</button>${content}</section></div>`}
function speak(text,lang='it-IT'){if(!('speechSynthesis'in window)){toast('이 기기에서는 음성 재생을 지원하지 않아요');return}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=.85;speechSynthesis.speak(u);toast('음성을 재생하고 있어요')}
function finishOrder(){state.extra=0;state.receiptCharges={coperto:0,water:0};state.lastOrder={cart:state.cart.map(r=>({...r})),total:total(),tipAmount:state.tip?Math.round(sum()*state.tipPercent)/100:0,tipPercent:state.tip?state.tipPercent:0,createdAt:new Date().toISOString()};save('lastOrder',state.lastOrder);go('receipt')}
function tasteModal(){modal(`<h2>내 입맛을 알려주세요</h2><label class="field-label">알레르기 <small>쉼표로 구분</small></label><input class="input" id="taste-allergy" value="${esc(state.allergies.join(', '))}" placeholder="예: 새우, 견과류"><label class="field-label">못 먹는 음식</label><input class="input" id="taste-avoid" value="${esc(state.avoid.join(', '))}"><label class="field-label">좋아하는 맛</label><input class="input" id="taste-prefs" value="${esc(state.prefs.join(', '))}"><div style="height:22px"></div>${btn('입맛 저장하기','data-action="save-taste"')}`)}
function invite(){modal(`<h2>맛있는 여행, 함께해요</h2><p class="muted">친구에게 초대 코드를 공유해보세요.<br>같은 메뉴판과 장바구니를 함께 볼 수 있어요.</p><div class="preview" style="text-align:center;font-size:30px;letter-spacing:6px;margin:25px 0">HANIP26</div>${btn('초대 코드 복사','data-action="copy-invite"')}<p class="subtle-note" style="text-align:center">프로토타입에서는 동반인 추가로 연결을 시연해요.</p>`)}
document.body.append($('#toast'));$('.device').append($('#overlay'));
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-detail],[data-enlarge-photo]');if(!el)return;if(el.dataset.detailPhrase){const i=find(el.dataset.detailPhrase);modal(`<h2>직원에게 확인해주세요</h2><div class="preview"><p>이 음식에 알레르기 유발 재료가 들어가나요? 제외할 수 있는지 확인해주세요.</p><p>Questo piatto contiene ingredienti che possono causare allergie? È possibile ometterli?</p></div><p class="subtle-note">${esc(foodName(i))} · ${esc(allergenText(i))}</p>`);return}if(el.dataset.showReviews){showDetailReviews(el.dataset.showReviews);return}if(el.dataset.detailPhoto){showDetailPhoto(el.dataset.detailPhoto);return}if(el.dataset.add){add(el.dataset.add);render();return}if(el.dataset.go){go(el.dataset.go);return}if(el.dataset.rank){const i=ranked().find(i=>i.id===el.dataset.rank);if(i)modal(`<span class="eyebrow">${esc(state.city.country)} · ${esc(state.city.ko)}</span><h2>${esc(i.korean)}</h2><p class="original">${esc(i.original)}</p><div class="ai-box"><span class="label">한국 음식으로 치면</span><p>${esc(i.analogy)}</p></div><div class="preview">${esc(i.description)}</div><p class="subtle-note">지역 대표 음식으로 구성한 시연용 랭킹이에요.</p>${btn('주변 식당 찾아보기',goAttr('nearby'),'secondary')}`);return}if(el.dataset.detail){state.selected=el.dataset.detail;go('detail');return}if(el.dataset.category){state.category=el.dataset.category;render();return}if(el.dataset.nearCategory){state.nearCategory=el.dataset.nearCategory;void loadExplorer(state.page);return}if(el.dataset.city){chooseCity(Number(el.dataset.city));return}if(el.hasAttribute('data-city')){chooseCity(0);return}if(el.dataset.qty){change(el.dataset.qty,el.dataset.owner,Number(el.dataset.delta));return}if(el.dataset.remove){state.cart=state.cart.filter(r=>!(r.id===el.dataset.remove&&r.owner===el.dataset.owner));save('cart',state.cart);render();return}if(el.hasAttribute('data-delete-photo')){state.photos.splice(Number(el.dataset.deletePhoto),1);render();return}if(el.hasAttribute('data-enlarge-photo')){let p=state.photos[Number(el.dataset.enlargePhoto)];modal(`<h2>촬영한 메뉴판</h2>${p?`<img src="${p}" alt="확대한 메뉴판" style="width:100%;border-radius:14px">`:'<div class="preview" style="font-size:22px;line-height:2"><b>Osteria La Solita Zuppa</b><br>— ZUPPE —<br>Zuppa di ceci e porcini<br>Zuppa di melanzane fumé<br>Zuppa di porri e patate<br>Zuppa di zucca e farro</div>'}<br>${btn('다시 촬영하기','data-go="camera"','secondary')}`);return}if(el.dataset.fоod)return;if(el.dataset.rating!==undefined){state.ratings[el.dataset.item]=Number(el.dataset.rating);save('ratings',state.ratings);render();later(()=>{state.review++;render()},450);return}if(el.dataset.friendAdd){state.friends.push(el.dataset.friendAdd);save('friends',state.friends);toast('여행 동반인으로 연결했어요');render();return}if(el.dataset.friendRemove){state.friends=state.friends.filter(n=>n!==el.dataset.friendRemove);save('friends',state.friends);render();return}if(el.dataset.editFriend){modal(`<h2>${esc(el.dataset.editFriend)}님 정보</h2><label class="field-label" for="friend-photo">프로필 사진</label><input class="input" id="friend-photo" type="file" accept="image/jpeg,image/png,image/webp"><label class="field-label">알레르기·못 먹는 음식</label><input class="input" id="friend-note" value="${esc(friendDescription(el.dataset.editFriend))}"><div style="height:20px"></div>${btn('저장하기',`data-save-friend="${esc(el.dataset.editFriend)}"`)}`);return}if(el.dataset.saveFriend){void saveFriendProfile(el.dataset.saveFriend);return}if(el.dataset.place){openPlace(el.dataset.place);return}if(el.dataset.savePlace){state.savedPlaces??=read('savedPlaces',[]);const id=el.dataset.savePlace;state.savedPlaces=state.savedPlaces.includes(id)?state.savedPlaces.filter(x=>x!==id):[...state.savedPlaces,id];save('savedPlaces',state.savedPlaces);render();return}if(el.dataset.restaurant){const p=nearbyPlaces.find(p=>p.name===el.dataset.restaurant);openPlace(p?.id||'solita','nearby');return}if(el.dataset.help){showHelp(el.dataset.help);return}const action=el.dataset.action;if(!action)return;switch(action){case'capture':try{appendPhoto(realCamera.capture($('#menu-camera')))}catch(error){toast(error.message)}break;case'album':pickPhotos();break;case'flash':realCamera.flash().then(on=>toast(on?'플래시 켜짐':'플래시 꺼짐')).catch(e=>toast(e.message));break;case'retry-scan':runScan();break;case'scan-search':searchRestaurants();break;case'scan-location':locateRestaurant();break;case'scan-map-area':state.scanLocation=state.mapSearchLocation;searchRestaurants('',true);break;case'scan-select':{state.restaurant=(state.scanPlaces||[]).find(p=>p.id===el.dataset.id);go('menu');void menuEnrichment.start(state.restaurant);break}case'scan-skip':state.restaurant=null;go('menu');void menuEnrichment.start(null);break;case'sheet':$('.map-sheet').classList.toggle('expanded');if($('#scanned-google-map'))$('#scanned-google-map').style.height=($('.map-sheet').classList.contains('expanded')?80:212)+'px';break;case'map-select':modal(`<h2>지도에서 식당 선택</h2><p class="muted">지도를 움직인 뒤 아래 식당을 선택해주세요.</p><div class="restaurant-row"><div><h3>Osteria La Solita Zuppa</h3><small>수프 · 파스타 · 고기 요리</small></div><button class="pill active" data-go="menu">선택</button></div>`);break;case'close-modal':$('#overlay').innerHTML='';break;case'invite':invite();break;case'copy-invite':navigator.clipboard?.writeText('HANIP26').then(()=>toast('초대 코드를 복사했어요')).catch(()=>toast('초대 코드: HANIP26'));break;case'menu-more':modal(`<h2>이 메뉴판에 대해</h2><p>Osteria La Solita Zuppa</p><p class="subtle-note">식당 공식 웹메뉴 보관 자료 · 2026.10.10<br>수프 4개 · 메인 요리 12개 · 칵테일 6개<br>시연 환율 €1 = ${rate}원</p>${btn('동반인 메뉴 담기 시연','data-action="simulate-companion"','secondary')}`);break;case'simulate-companion':add(items[3].id,state.friends[0]||'김미영',false);$('#overlay').innerHTML='';render();toast('김미영님이 담았어요',items[3]);break;case'allergen-phrase':modal(`<h2>직원에게 확인해주세요</h2><div class="preview"><p>이 음식에 ${esc([...state.avoid,...state.allergies].join(', ')||'알레르기 유발 재료')}가 들어가나요?</p><p>Mi può dire se questo piatto contiene funghi o melanzane?</p></div><br>${btn(icon('sound')+' 현지어 듣기','data-action="speak-allergen"')}`);break;case'speak-allergen':speak('Mi può dire se questo piatto contiene funghi o melanzane?');break;case'speak-order':speak(orderSentences().it);break;case'speak-staff':speak(state.conversationPhase===1?orderSentences().it:'Certamente, va bene.');break;case'speak-korean':speak('네, 알겠습니다.','ko-KR');break;case'show-order':$('#overlay').innerHTML='';state.conversationPhase=1;render();later(()=>{state.conversationPhase=2;render()},5000);break;case'skip-order':$('#overlay').innerHTML='';state.conversationPhase=2;render();break;case'my-speak':state.conversationPhase=3;render();later(()=>{state.conversationPhase=2;render()},2500);break;case'staff-speak':state.conversationPhase=2;render();break;case'finish-order':finishOrder();break;case'edit-profile':modal(`<h2>프로필 수정</h2><label class="field-label">이름</label><input class="input" id="profile-name" value="${esc(state.name)}" maxlength="20"><div style="height:22px"></div>${btn('저장하기','data-action="save-profile"')}`);break;case'save-profile':state.name=$('#profile-name').value.trim()||state.name;save('name',state.name);$('#overlay').innerHTML='';render();toast('프로필을 저장했어요');break;case'taste':tasteModal();break;case'save-taste':{const parse=s=>s.split(/[,，]/).map(s=>s.trim()).filter(Boolean);state.avoid=parse($('#taste-avoid').value);state.allergies=parse($('#taste-allergy').value);state.prefs=parse($('#taste-prefs').value);['avoid','allergies','prefs'].forEach(k=>save(k,state[k]));$('#overlay').innerHTML='';render();toast('내 입맛을 저장했어요');break}case'new-friend':modal(`<h2>새 친구 등록</h2><label class="field-label">이름</label><input class="input" id="new-friend" placeholder="친구 이름" maxlength="20"><div style="height:22px"></div>${btn('동반인으로 추가','data-action="save-new-friend"')}`);break;case'save-new-friend':{let n=$('#new-friend').value.trim();if(!n){toast('이름을 입력해주세요');break}if(!state.friends.includes(n))state.friends.push(n);save('friends',state.friends);$('#overlay').innerHTML='';render();break}case'clear-search':state.query='';$('#city-query').value='';startSearch();break;case'old-order':modal(`<h2>Trattoria Da Rosa</h2><p class="muted">피렌체 · 2026.10.24 · 2명</p><div class="preview" style="margin:20px 0">소고기 요리 2개<br>음식 및 확인한 추가 요금 <b>€ 38.50</b></div>${btn('닫기','data-action="close-modal"','secondary')}`);break}});
function chooseCity(n){let r=state.cityRows[n];if(!r)return;state.pendingCity=r;modal(`<span class="eyebrow">YOUR NEXT DESTINATION</span><h2>${esc(r.country)} · ${esc(r.ko||r.name)}</h2><p class="muted">${esc(r.name)} · ${esc(r.region||'')}</p><p class="subtle-note">여행지와 지역별 추천 기준을 이 도시로 변경할까요?</p>${btn('이 도시로 여행하기','data-action="confirm-city"')}`)}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="confirm-city"]')){state.city=state.pendingCity;save('city',state.city);go('home');toast('여행지를 변경했어요')}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='tip-custom'){const n=Number(e.target.value);if(e.target.value.trim()&&Number.isFinite(n)&&n>=0&&n<=100){state.tipPercent=Math.round(n*10)/10;state.tip=n>0;$('#tip').checked=state.tip;$('#tip-percent').value='custom';$('#cart-tip-amount').textContent=state.tip?'선택 팁 '+money(sum()*state.tipPercent/100):'팁 미포함';$('#cart-total-won').textContent=`총 ${count()}개 · ${won(total())}`;$('#cart-total-amount').textContent=money(total())}}if(e.target.id==='city-query'){state.query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(startSearch,250)}if(e.target.id==='request'){state.request=e.target.value;const s=orderSentences();$('#order-ko').textContent=s.ko;$('#order-it').textContent=s.it;$('#request-status').textContent=!state.request.trim()?'':!requestTranslation(state.request)?'이 요청은 시연 번역 범위 밖이에요. 치즈 제외·재료 추가·맵기·물 요청을 입력해보세요.':'자연스러운 이탈리아어 표현으로 주문 문장에 반영했어요.'}if(e.target.id==='extra'){state.extra=Math.max(0,Math.min(10000,Number(e.target.value)||0));let base=(state.lastOrder?.cart||state.cart).reduce((s,r)=>s+find(r.id).price*r.qty,0);updateReceiptTotals()}});
document.addEventListener('change',e=>{if(e.target.id==='country-select'){state.country=e.target.value;startSearch()}if(e.target.id==='tip'){state.tip=e.target.checked;render()}if(e.target.id==='tip-percent'){if(e.target.value==='custom'){state.tipCustom=true;render();$('#tip-custom').focus();$('#tip-custom').select()}else{state.tipCustom=false;state.tipPercent=Number(e.target.value);state.tip=state.tipPercent>0;render()}}if(e.target.id==='tip-custom'){const n=Number(e.target.value);state.tipPercent=e.target.value.trim()&&Number.isFinite(n)?Math.round(Math.max(0,Math.min(100,n))*10)/10:5;state.tip=state.tipPercent>0;render()}if(e.target.dataset.setting){state.settings[e.target.dataset.setting]=e.target.checked;save('settings',state.settings);toast('설정을 저장했어요')}if(e.target.id==='font-size'){state.settings.font=e.target.value;save('settings',state.settings);$('.device').style.setProperty('--font-large',e.target.value==='large'?'1':'0');toast(e.target.value==='large'?'큰 글자 모드를 적용했어요':'기본 글자 크기로 변경했어요');render()}if(e.target.id==='language'){state.settings.language=e.target.value;save('settings',state.settings);toast('표시 언어 설정을 저장했어요 · 화면은 한국어 시연이에요')}});
