function showHelp(t){modal(`<h2>${t}</h2>${t==='사용 안내'?'<p>메뉴판 찍기 → 사진 확인 → 해석 → 식당 선택 → 메뉴 고르기 → 장바구니 → 주문 문장 → 마주보기 대화 → 영수증 순서로 둘러보세요.</p><p class="subtle-note">사진은 실제 카메라로 촬영하거나 앨범에서 추가할 수 있어요. 촬영과 AI 해석·식당 검색은 실제 연결 기능이에요. 동반인 담기 알림은 메뉴판 진입 후 한 번 자동으로 재생돼요.</p>':t==='개인정보 및 저장'?'<p>도시·입맛 설정·장바구니·평가 기록은 현재 브라우저에 저장돼요. 촬영 사진은 해석하기를 누를 때 Gemini로 전송해요. 사진 원본은 서버에 저장하지 않으며, 현재 탭을 닫으면 사라져요. 해석한 메뉴는 현재 탭에서 확인할 수 있어요.</p><p class="subtle-note">홈과 주변 장소에는 예시 데이터가 남아 있어요. 실제 촬영 메뉴의 AI 해석과 구글 식당 검색은 서버 API로 처리해요. 동반인 연결·주문 통역·실시간 환율은 후속 구현 단계예요. 도시 검색은 실제 지명 데이터에서 수행해요.</p>':'<p>한입 · 유럽 미식 가이드</p><p class="subtle-note">Galaxy S26 비율의 디자인 프로토타입<br>메뉴 출처: Osteria La Solita Zuppa 공식 웹메뉴, 2026.10.10 보관 자료<br>식당 대표 사진: <a href="https://maps.app.goo.gl/L96ZagCk13Fdoeoy5" target="_blank" rel="noopener">Osteria La Solita Zuppa · Google Maps 소유자 제공</a><br>도시 데이터: <a href="https://www.geonames.org/" target="_blank" rel="noopener">GeoNames</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a><br>한국어 별칭 및 근사 발음 표기를 포함해 가공했어요.</p>'}<br>${btn('확인','data-action="close-modal"','secondary')}`)}
const realCamera=new MenuCamera();let scanController=null,placeController=null,placeSearchSerial=0;
function mountCamera(){const video=$('#menu-camera');if(!video)return;realCamera.mount(video,message=>{const el=$('#camera-message');if(el){el.textContent=message;el.classList.add('visible')}}).then(()=>{const el=$('#camera-message');if(el&&!realCamera.error)el.classList.remove('visible')})}
function appendPhoto(data){if(state.photos.length>=8){toast('최대 8장까지 해석할 수 있어요.');return}if(state.photos.reduce((n,p)=>n+p.length,0)+data.length>9500000){toast('전체 사진 용량이 커요. 사진을 나눠 해석해주세요.');return}state.photos.push(data);state.scanError='';render();toast(`${state.photos.length}장 촬영했어요`,null,800)}
async function pickPhotos(){
 let input=document.getElementById('menu-photo-input');
 if(!input){input=document.createElement('input');input.id='menu-photo-input';input.type='file';input.accept='image/*';input.multiple=true;input.hidden=true;input.setAttribute('aria-label','메뉴판 사진 파일');document.body.append(input);}
 input.value='';
 input.onchange=async()=>{const files=Array.from(input.files||[]);for(const f of files){if(state.photos.length>=8){toast('최대 8장까지 선택할 수 있어요.');break}try{appendPhoto(await readPhoto(f))}catch(e){toast(e.message)}}};
 input.click();
}
async function runScan(){
 if(scanController)return;
 state.scanError='';state.analysis=0;
 if(!state.photos.length){state.scanError='해석할 메뉴판 사진을 먼저 찍어주세요.';render();return}
 const controller=new AbortController();scanController=controller;render();
 try{
  const {menu}=await requestJson('/api/menu/recognize',{images:state.photos},controller.signal);
  if(controller.signal.aborted)return;
  state.liveMenu=menu;items=menu.items;Object.assign(categoryNames,menu.categories);state.category=items[0].category;state.cart=[];save('cart',[]);state.selected=null;state.restaurant=null;state.scanPlaces=[];state.placeError='';state.analysis=1;render();
  if(menu.restaurantName){
   try{const result=await requestJson('/api/menu/places',{name:menu.restaurantName,location:state.scanLocation},controller.signal);state.scanPlaces=result.places;state.scanProvider=result.provider;state.scanAttribution=result.attribution;if(!result.places.length)state.placeError='일치하는 식당을 찾지 못했어요. 이름을 수정하거나 현재 위치로 찾아주세요.'}catch(e){if(controller.signal.aborted)return;state.placeError=e.message}
  }
  state.analysis=2;scanController=null;go('restaurant');
 }catch(e){if(!controller.signal.aborted){state.scanError=e.message;render()}}finally{if(scanController===controller)scanController=null}
}
async function searchRestaurants(name=$('#scan-place-name')?.value||'',useLocation=false){
 if(!name.trim()&&!useLocation){state.placeError='식당 이름을 입력하거나 현재 위치로 찾아주세요.';render();return}
 const serial=++placeSearchSerial;placeController?.abort();const controller=new AbortController();placeController=controller;
 state.searchingPlaces=true;state.placeSearch=name;state.placeError='';render();
 try{const r=await requestJson('/api/menu/places',{name:useLocation?'':name,location:state.scanLocation},controller.signal);if(serial!==placeSearchSerial)return;state.scanPlaces=r.places;state.scanProvider=r.provider;state.scanAttribution=r.attribution;if(!r.places.length)state.placeError='검색 결과가 없어요. 식당 이름을 다시 확인해주세요.'}
 catch(e){if(!controller.signal.aborted)state.placeError=e.message}finally{if(serial===placeSearchSerial){state.searchingPlaces=false;if(state.page==='restaurant')render()}}
}
async function locateRestaurant(){try{state.placeError='현재 위치를 확인하고 있어요.';render();state.scanLocation=await locate();await searchRestaurants('',true)}catch(e){state.placeError=e.message;render()}}
function scanMap(){return '<div class="map google-menu-map" id="scanned-google-map" aria-label="구글 식당 지도">구글 지도를 불러오는 중이에요.</div>'}
function mountScannedMap(){const container=$('#scanned-google-map');if(!container)return;mountGoogleMap(container,state.scanPlaces||[],state.scanLocation,id=>{const row=document.querySelector(`[data-scan-place="${CSS.escape(id)}"]`);row?.scrollIntoView({behavior:'smooth',block:'nearest'});row?.classList.add('highlight')},position=>{state.mapSearchLocation=position;const button=$('#scan-map-area');if(button)button.hidden=false})}
function scannedRestaurant(){const rows=state.scanPlaces||[],first=rows[0];return wrap(`<div class="map-screen restaurant-confirm-screen">${scanMap()}${top('','photos')}<div class="map-sheet"><button class="handle" data-action="sheet" aria-label="식당 패널 펼치기"></button><div class="sheet-scroll"><button id="scan-map-area" class="pill" data-action="scan-map-area" hidden>이 지도 영역에서 식당 찾기</button><span class="restaurant-region">${state.liveMenu.restaurantName?'메뉴판에서 찾은 식당명':'메뉴판에서 식당명을 찾지 못했어요'}</span><h2 class="restaurant-sheet-title">${esc(state.liveMenu.restaurantName||'어느 식당인가요?')}</h2>${first?'':'<p class="restaurant-question">식당 이름이나 현재 위치로 찾아주세요.</p>'}<div class="scan-place-search"><input id="scan-place-name" class="input" placeholder="식당 이름 검색" aria-label="식당 이름 검색" value="${esc(state.placeSearch??state.liveMenu.restaurantName)}"><button class="icon-btn" data-action="scan-search" aria-label="식당 검색" ${state.searchingPlaces?'disabled':''}>${icon('search')}</button></div><button class="pill" data-action="scan-location" ${state.searchingPlaces?'disabled':''}>${icon('pin')} 현재 위치로 주변 식당 찾기</button>${state.searchingPlaces?'<p role="status">식당을 찾고 있어요…</p>':''}${state.placeError?`<p class="scan-error" role="alert">${esc(state.placeError)}</p>`:''}<div class="scan-place-results">${rows.map((p,n)=>`<article class="scan-place-card" data-scan-place="${esc(p.id)}">${p.photo?`<img class="scan-google-photo" src="${esc(apiAssetUrl(p.photo.url))}" alt="${esc(p.name)} · Google Maps 사진"><div class="google-photo-authors">${p.photo.authors.map(a=>a.url?`<a href="${esc(a.url)}" target="_blank" rel="noopener">${esc(a.name)}</a>`:esc(a.name)).join(' · ')}${p.photo.maps?` · <a href="${esc(p.photo.maps)}" target="_blank" rel="noopener">원본 사진 ↗</a>`:''}</div>`:''}<span class="small muted">${n===0?'가장 먼저 확인할 후보':'다른 식당 후보'}</span><h3>${esc(p.name)}</h3><p>${esc(p.type)}${p.businessStatus==='CLOSED_PERMANENTLY'?' · 폐업':p.businessStatus==='CLOSED_TEMPORARILY'?' · 임시 휴업':''}</p>${p.rating!==null?`<p>★ ${Number(p.rating).toFixed(1)} · 리뷰 ${Number(p.ratingCount).toLocaleString()}개</p>`:'<small>구글에서 제공한 평점 정보가 없어요.</small>'}<p class="small">${esc(p.address)}</p>${p.hours?.length?`<details><summary>영업시간</summary>${p.hours.map(h=>`<p class="small">${esc(h)}</p>`).join('')}</details>`:''}<div class="scan-place-actions">${p.maps?`<a class="pill" href="${esc(p.maps)}" target="_blank" rel="noopener">지도에서 보기 ↗</a>`:''}${p.website?`<a class="pill" href="${esc(p.website)}" target="_blank" rel="noopener">공식 사이트 ↗</a>`:''}<button class="pill active" data-action="scan-select" data-id="${esc(p.id)}" ${p.businessStatus==='CLOSED_PERMANENTLY'?'disabled':''}>이 식당이 맞아요</button></div></article>`).join('')}</div><p class="subtle-note"><span class="GMP-attribution" translate="no">Google Maps</span><br>검색 후보가 실제 식당과 일치하는지 확인해주세요.</p>${btn('식당 연결 없이 메뉴 보기','data-action="scan-skip"','secondary')}</div></div></div>`)}
function scanPrice(i){return i.price===null?'가격 확인 필요':`${esc(state.liveMenu.currency||'통화 확인 필요')} ${i.price.toFixed(2)}`}
function scannedMenu(){const categories=Object.keys(state.liveMenu.categories);return wrap(`${top('메뉴를 골라주세요','restaurant')}<div class="menu-header"><p class="small">${esc(state.restaurant?.name||state.liveMenu.restaurantName||'촬영한 메뉴판')}</p><div class="tabs menu-category-tabs" role="tablist" aria-label="메뉴 카테고리">${categories.map(c=>`<button class="${state.category===c?'active':''}" data-category="${esc(c)}" role="tab" aria-selected="${state.category===c}">${esc(c)}<span>${items.filter(i=>i.category===c).length}</span></button>`).join('')}</div></div><div class="scroll" style="padding-top:0">${menuEnrichment.markup()}<div class="food-grid">${items.filter(i=>i.category===state.category).map(i=>`<article class="food-card scan-food-card" tabindex="0" role="button" data-detail="${i.id}"><div class="scan-food-icon">${icon('receipt')}<span>촬영 메뉴</span>${warning(i).length?`<div class="food-photo-warnings">${warning(i).map(t=>`<span>${esc(t)} 확인</span>`).join('')}</div>`:''}</div><div class="food-copy"><span class="original">${esc(i.original)}</span><h3>${esc(i.korean)}</h3><p>${esc(i.enrichment?.summary||i.listDescription)}</p>${enrichmentBadge(i)}<div class="price">${scanPrice(i)}</div></div></article>`).join('')}</div><p class="subtle-note">메뉴명·가격·판매 표시는 촬영한 메뉴판 기준이에요. 웹에서 찾은 설명은 출처를 함께 표시해요. 메뉴에 없는 음식 사진·평점은 표시하지 않아요.<br>원화 환산과 실제 주문 연결은 다음 단계에서 제공해요.</p>${state.liveMenu.notes?.length?`<p class="subtle-note">${state.liveMenu.notes.map(esc).join('<br>')}</p>`:''}</div>`)}
function scannedDetail(){const i=find(state.selected)||items[0];return wrap(`${top('메뉴 자세히','menu')}<div class="scan-detail-summary scan-detail"><div class="detail-meta-row"><span class="original">${esc(i.original)}</span>${warning(i).length?`<div class="detail-ingredient-badges">${warning(i).map(t=>`<span class="detail-ingredient-badge">${esc(t)} 포함</span>`).join('')}</div>`:''}</div><div class="detail-title-row"><h2>${esc(i.korean)}</h2></div><div class="detail-price">${scanPrice(i)}</div></div><div class="scroll scan-detail">${menuEnrichment.markup()}${externalDetail(i)}<div class="ai-box"><p class="ai-analogy-intro"><span class="ai-analogy-sparkle" aria-hidden="true">✦</span> AI가 한국 음식에 빗대어 설명했어요</p><span class="label">한국 음식으로 치면</span><h3>${esc(i.enrichment?.analogy||i.analogy||i.listDescription||'익숙한 음식과 비교할 정보가 부족해요.')}</h3><p>AI가 이해를 돕기 위해 비교했어요. 실제 조리법과 다를 수 있어요.</p></div><div class="info-card"><h3>메뉴판에서 확인한 정보</h3><p>${esc(i.description||'메뉴 이름과 가격 외의 설명은 확인되지 않았어요.')}</p><div class="divider"></div><small>명시된 재료</small><p>${esc(i.ingredients.join(' · ')||'따로 표시되지 않았어요.')}</p><small>명시된 알레르기</small><p>${esc(i.allergens.join(' · ')||'표시를 확인하지 못했어요. 알레르기 유발 재료가 없다는 뜻은 아니에요.')}</p><details><summary>원문 확인${i.page?' · 사진 '+i.page:''}</summary><p>${esc(i.evidence||i.original)}</p>${i.page&&state.photos[i.page-1]?`<img class="scan-source-photo" src="${state.photos[i.page-1]}" alt="해당 메뉴가 있는 촬영 사진">`:''}</details></div><div class="ai-box"><span class="label">✦ AI가 보충한 음식 이야기</span><p class="small">일반적인 음식 특성이며 이 식당에서 확인한 정보는 아니에요.</p><div class="divider"></div><small>맛과 식감</small><p>${esc(i.taste||'추가 확인이 필요해요.')}</p><small>조리법</small><p>${esc(i.cooking||'메뉴판만으로 확인되지 않아요.')}</p>${i.inferredIngredients.length?`<small>일반적으로 쓰일 수 있는 재료</small><p>${esc(i.inferredIngredients.join(' · '))}</p>`:''}${i.uncertainty?`<p>${esc(i.uncertainty)}</p>`:''}</div><p class="subtle-note">알레르기와 제외할 재료는 주문 전 직원에게 꼭 확인해주세요.</p></div>`)}
window.addEventListener('pagehide',()=>{realCamera.stop();scanController?.abort();placeController?.abort();menuEnrichment.cancel()});
window.addEventListener('pageshow',()=>{if(state.page==='camera')mountCamera()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)realCamera.stop();else if(state.page==='camera')mountCamera()});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='scan-place-name')searchRestaurants()});

try{state.restaurantPreview=await fetch('restaurant-preview.json').then(r=>r.ok?r.json():null).catch(()=>null);items=koreanDiningPayload(await fetch('menu.json').then(r=>r.json())).map(i=>({...i,category:i.category.toLowerCase()}));state.cart=state.cart.filter(r=>find(r.id));state.lastOrder=read('lastOrder',{cart:[{id:items[2].id,owner:'나',qty:1},{id:items[3].id,owner:'김미영',qty:1},{id:items[7].id,owner:'김미영',qty:1}],total:35});state.friendNotes=read('friendNotes',{});state.friendPhotos=read('friendPhotos',{});state.savedPlaces=read('savedPlaces',[]);window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);if(p&&p!==state.page)go(p)});const requested=location.hash.slice(1);go(['home','camera','menu','history','my','friends','destination','ranking','nearby','asian','restaurant','analysis-preview','receipt','cart','order','detail','photos'].includes(requested)?requested:'home')}catch(e){$('#app').innerHTML='<div class="empty">메뉴 자료를 불러오지 못했어요.<br>페이지를 새로고침해주세요.</div>';console.error(e)}

let dragState;document.addEventListener('pointerdown',e=>{if(!e.target.closest('.handle'))return;const sheet=$('.map-sheet');dragState={sheet,start:e.clientY,top:sheet.offsetTop};e.target.setPointerCapture(e.pointerId)});document.addEventListener('pointermove',e=>{if(!dragState)return;const ratio=$('.device').getBoundingClientRect().height/$('.device').offsetHeight;const top=Math.max(65,Math.min(400,dragState.top+(e.clientY-dragState.start)/ratio));dragState.sheet.style.top=top+'px';if($('#scanned-google-map'))$('#scanned-google-map').style.height=top+'px'});document.addEventListener('pointerup',()=>{dragState=null});

document.addEventListener('input',e=>{if(['receipt-coperto','receipt-water'].includes(e.target.id)){state.receiptCharges??={};state.receiptCharges[e.target.id==='receipt-coperto'?'coperto':'water']=Math.max(0,Math.min(10000,Number(e.target.value)||0));updateReceiptTotals()}});
